import java.io.*;
import java.util.*;

public class VariantsSolution {
    static Scanner scannerInstance;
    static PrintWriter outputWriter;
    static long module = 1_000_000_000L + 7;

    public static void main(String[] args) throws Exception {
        StringBuilder dataSample = new StringBuilder();
        if (dataSample.length() == 0) {
            scannerInstance = new Scanner(System.in);
        } else {
            scannerInstance = new Scanner(new StringReader(dataSample.toString()));
        }
        outputWriter = new PrintWriter(new OutputStreamWriter(System.out));
        initializeData();
        processSolution();
        outputWriter.flush();
    }

    private static void initializeData() {
        // No specific initialization needed
    }

    private static void processSolution() throws IOException {
        int aCount = scannerInstance.nextInt();
        int bCount = scannerInstance.nextInt();
        int fromIndex = scannerInstance.nextInt() - 1;
        int toIndex = scannerInstance.nextInt() - 1;
        int segmentRange = toIndex - fromIndex + 1;
        int minimumSum = segmentRange;

        for (char c1 = 'a'; c1 <= 'z'; c1++)
            for (char c2 = 'a'; c2 <= 'z'; c2++)
                for (char c3 = 'a'; c3 <= 'z'; c3++)
                    minimumSum = Math.min(minimumSum, evaluateOverlap(aCount, bCount, fromIndex, toIndex, new char[]{c1, c2, c3}));

        outputWriter.println(minimumSum);
    }

    private static int evaluateOverlap(int a, int b, int startIdx, int endIdx, char[] patternChars) {
        char[] buffer = new char[3 * (a + b)];
        for (int segmentIdx = 0; segmentIdx < 3; segmentIdx++) {
            System.arraycopy(collectDistinctChars(buffer, segmentIdx * (a + b), a), 0, buffer, segmentIdx * (a + b), a);
            Arrays.fill(buffer, segmentIdx * (a + b) + a, (segmentIdx + 1) * (a + b), patternChars[segmentIdx]);
        }

        int offset = startIdx % (a + b);
        int length = endIdx - startIdx + 1;
        buffer = Arrays.copyOfRange(buffer, offset, buffer.length);
        buffer = Arrays.copyOf(buffer, Math.min(buffer.length, length));

        boolean[] visited = new boolean[26];
        for (char c : buffer) {
            visited[c - 'a'] = true;
        }

        int countTypes = 0;
        for (boolean v : visited) {
            if (v) countTypes++;
        }
        return countTypes;
    }

    private static char[] collectDistinctChars(char[] arr, int idx, int count) {
        boolean[] usedLetters = new boolean[26];
        for (int f = idx - 1; f >= 0 && f >= idx - count; f--) {
            usedLetters[arr[f] - 'a'] = true;
        }
        char[] res = new char[count];
        char chPointer = 'a';
        int cr = 0;
        while (cr < count) {
            while (usedLetters[chPointer - 'a']) chPointer++;
            res[cr++] = chPointer++;
        }
        return res;
    }

    private static int readNextInt() throws IOException {
        return Integer.parseInt(scannerInstance.nextLine().trim());
    }
}
